import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import '../../../core/providers/app_providers.dart';import '../../discover/data/content_update_service.dart';
class ContentUpdatesScreen extends ConsumerStatefulWidget{const ContentUpdatesScreen({super.key});@override ConsumerState<ContentUpdatesScreen> createState()=>_ContentUpdatesScreenState();}
class _ContentUpdatesScreenState extends ConsumerState<ContentUpdatesScreen>{bool busy=false;String? message;static const manifestUrl=String.fromEnvironment('PAWPAL_CONTENT_MANIFEST_URL');
Future<void> check()async{if(manifestUrl.isEmpty){setState(()=>message='No public content manifest is configured. Build with --dart-define=PAWPAL_CONTENT_MANIFEST_URL=https://raw.githubusercontent.com/OWNER/REPO/main/manifest.json. No personal data is sent.');return;}setState(()=>busy=true);final service=ContentUpdateService();try{final result=await service.checkAndDownload(Uri.parse(manifestUrl));await ref.read(appControllerProvider).repository.db.setPreference('content_version',result.version);await ref.read(appControllerProvider).repository.db.setPreference('content_last_success',result.updatedAt.toIso8601String());if(mounted)setState(()=>message='Installed content version ${result.version}. ${result.files.length} files validated and cached.');}catch(e){if(mounted)setState(()=>message='Update not installed. The last validated content pack remains unchanged. $e');}finally{await service.close();if(mounted)setState(()=>busy=false);}}
@override Widget build(BuildContext context){final c=ref.watch(appControllerProvider);return Scaffold(appBar:AppBar(title:const Text('Content updates')),body:ListView(padding:const EdgeInsets.all(20),children:[const Text('PawPal downloads only public editorial JSON from an HTTPS GitHub raw-content URL. Pet profiles, notes, reminders, records and device identifiers are never included in content requests.'),const SizedBox(height:14),FutureBuilder<String?>(future:c.repository.db.getPreference('content_version'),builder:(context,s)=>Card(child:ListTile(leading:const Icon(Icons.library_books_outlined),title:const Text('Installed content'),subtitle:Text(s.data??'Bundled starter pack')))),FilledButton.icon(onPressed:busy?null:check,icon:const Icon(Icons.sync),label:Text(busy?'Checking…':'Check for updates')),if(message!=null)...[const SizedBox(height:14),SelectableText(message!)],const SizedBox(height:14),const Text('The manifest and every file are checked for schema, allowlisted path, file size and SHA-256 before the new version is activated. Failed downloads do not replace the previous pack.') ]));}}
